#!/usr/bin/env bash
# Deploy saldo BetBra na VPS (root). Sem GitHub API. Cole inteiro.
set -euo pipefail
WEB="${BOTSHIELD_WEB:-/var/www/arbishield-botshield}"
SHIM="${ARBISHIELD_SHIM_DIR:-/opt/arbishield}"
SCR="${ARBISHIELD_SCRIPTS:-$SHIM/scripts}"
python3 - "$WEB" "$SHIM" "$SCR" <<'PY'
import base64, zlib, hashlib, sys
from pathlib import Path
web, shim, scr = sys.argv[1], sys.argv[2], sys.argv[3]
def put(paths, b64, sha):
    data = zlib.decompress(base64.b64decode(''.join(b64.split())))
    digest = hashlib.sha256(data).hexdigest()
    if digest != sha:
        raise SystemExit(f'SHA mismatch {paths[0]}: got {digest}')
    for rel in paths:
        p = Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print('OK', p, len(data))

