ROUTE = r'''
  if (url.pathname === "/api/arbishield/exchange-session/balance" && req.method === "GET") {
    try {
      if (!exchangeOrdersApi) {
        return sendJson(res, 503, { error: "exchange-orders-service ausente" });
      }
      if (typeof exchangeOrdersApi.sessionBalance !== "function") {
        return sendJson(res, 503, {
          error:
            "API de saldo desatualizada — atualize exchange-orders-service.mjs na VPS",
        });
      }
      const token = bearerFromReq(req);
      const out = await exchangeOrdersApi.sessionBalance(token, {
        provider: url.searchParams.get("provider") || "betbra",
      });
      return sendJson(res, 200, out);
    } catch (err) {
      return sendJson(res, err.status || 400, {
        ok: false,
        error: err instanceof Error ? err.message : String(err),
        code: err.code || undefined,
      });
    }
  }
'''
marker = 'if (url.pathname === "/api/arbishield/exchange-orders/place"'
for sp in [Path(shim)/'arbishield-serverfn-shim.mjs', Path(scr)/'arbishield-serverfn-shim.mjs']:
    if not sp.is_file():
        continue
    text = sp.read_text(encoding='utf-8')
    if 'exchange-session/balance' in text:
        print('shim já tem balance:', sp)
        continue
    if marker not in text:
        raise SystemExit('âncora place não encontrada em '+str(sp))
    text = text.replace(marker, ROUTE + '\n  ' + marker, 1)
    sp.write_text(text, encoding='utf-8')
    print('shim OK', sp)
print('PATCH SALDO OK')
PY
systemctl restart arbishield-serverfn-shim.service 2>/dev/null || true
